package com.eps.entity;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import javax.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.LocalDateTime;

/**
 * General ledger voucher entity, mapped to table EPSGLV.
 * Represents an accounting entry generated by the EPS system
 * for posting payment transactions to the general ledger.
 * Each voucher debits one account and credits another.
 */
@Entity
@Table(name = "EPSGLV")
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class GlVoucher {

    /** Unique voucher number, length 20 */
    @Id
    @Column(name = "VOUCHER_NO", length = 20, nullable = false)
    private String voucherNo;

    /** Reference to the originating payment instruction, length 20 */
    @Column(name = "PAYMENT_REF", length = 20)
    private String paymentRef;

    /** Posting date for the accounting entry */
    @Column(name = "POST_DATE")
    private LocalDate postDate;

    /** ISO 4217 currency code, length 3 (e.g. SGD, USD) */
    @Column(name = "CURRENCY", length = 3)
    private String currency;

    /** Voucher amount in the stated currency */
    @Column(name = "AMOUNT", precision = 18, scale = 2)
    private BigDecimal amount;

    /** Debit side account number, length 30 */
    @Column(name = "DEBIT_ACCOUNT", length = 30)
    private String debitAccount;

    /** Credit side account number, length 30 */
    @Column(name = "CREDIT_ACCOUNT", length = 30)
    private String creditAccount;

    /** Free-text narrative for the accounting entry, length 140 */
    @Column(name = "NARRATIVE", length = 140)
    private String narrative;

    /**
     * Posting status of the voucher.
     * P = Pending, S = Sent/Posted, E = Error.
     * See {@code PostStatus} enum for allowed values.
     */
    @Column(name = "POST_STATUS", length = 1)
    private String postStatus;

    /** Timestamp when the voucher was successfully posted to the GL */
    @Column(name = "POST_TIME")
    private LocalDateTime postTime;

    /** Error message if the GL posting failed, length 200 */
    @Column(name = "ERROR_MESSAGE", length = 200)
    private String errorMessage;

    /** Filename of the GL interface file generated, length 50 */
    @Column(name = "GL_INTERFACE_FILE", length = 50)
    private String glInterfaceFile;
}
